let currentLanguage="es";
const $=(selector)=>document.querySelector(selector);
function t(key){return translations[currentLanguage]?.[key]||translations.es[key]||key}
function renderDepartments(query=""){
 const grid=$("#department-grid"); if(!grid)return;
 const list=departments.filter(d=>(d.name+" "+d.capital+" "+d.towns).toLowerCase().includes(query.toLowerCase()));
 grid.innerHTML=list.map(d=>{const idx=departments.indexOf(d);const name=departmentNames[currentLanguage]?.[idx]||d.name;return `<article class="department-card" tabindex="0" role="button" data-dept="${d.id}" aria-label="${name}, ${t("capital")}: ${d.capital}"><span class="dept-number">${String(idx+1).padStart(2,"0")} / 19</span><strong>${name}</strong><small>${t("capital")}: ${d.capital}</small></article>`}).join("");
 $("#department-count").textContent=list.length+" / 19 "+t("departments");
 grid.querySelectorAll("[data-dept]").forEach(card=>{const open=()=>showDepartment(card.dataset.dept);card.addEventListener("click",open);card.addEventListener("keydown",e=>{if(e.key==="Enter"||e.key===" "){e.preventDefault();open()}})});
 if(!list.length)grid.innerHTML=`<p class="map-note">${t("search_none")}</p>`;
}
function showDepartment(id){
 const d=departments.find(x=>x.id===id);if(!d)return;
 const idx=departments.indexOf(d),name=departmentNames[currentLanguage]?.[idx]||d.name,extraLang=extra[currentLanguage]||extra.es;
 $("#department-detail").innerHTML=`<div class="dialog-content"><div class="section-kicker">URUGUAY · ${String(idx+1).padStart(2,"0")} / 19</div><h2>${name}</h2><div class="dialog-meta"><div><strong>${t("capital")}</strong>${d.capital}</div><div><strong>${t("region")}</strong>${d.region}</div><div><strong>${t("area")}</strong>${d.area}</div><div><strong>${t("population")}</strong>${d.population}*</div></div><h3>${t("overview")}</h3><p>${extraLang.about}</p><p>${d.story}</p><h3>${t("landscape")}</h3><p>${d.land}</p><p>${extraLang.nature}</p><h3>${t("identity_title")}</h3><p>${extraLang.history}</p><p><strong>${t("food")}:</strong> ${extraLang.food}</p><p><strong>${t("celebrations")}:</strong> ${extraLang.events}</p><h3>${t("highlights_title")}</h3><p>${d.discover}</p><p><strong>Localidades:</strong> ${d.towns}.</p><p><small>* ${t("population")} estimación de población al 31 de mayo de 2023, publicada por el INE en el Anuario Estadístico Nacional 2025. Consulta la <a href="https://www.gub.uy/instituto-nacional-estadistica/comunicacion/publicaciones/anuario-estadistico-nacional-2025-vol-102/21-informacion-censal/211" target="_blank" rel="noopener">tabla oficial por departamento</a>.</small></p></div>`;
 $("#department-dialog").showModal();
}
function applyLanguage(lang){
 currentLanguage=translations[lang]?lang:"es";document.documentElement.lang=currentLanguage;$("#language").value=currentLanguage;
 document.querySelectorAll("[data-i18n]").forEach(el=>{const value=t(el.dataset.i18n);if(value)el.innerHTML=value});
 document.querySelectorAll("[data-i18n-placeholder]").forEach(el=>{el.placeholder=t(el.dataset.i18nPlaceholder)});
 renderDepartments($("#department-search").value);
}
$("#language").addEventListener("change",e=>applyLanguage(e.target.value));
$("#department-search").addEventListener("input",e=>renderDepartments(e.target.value));
$("#menu-toggle").addEventListener("click",()=>{const nav=$("#main-nav"),open=nav.classList.toggle("open");$("#menu-toggle").setAttribute("aria-expanded",String(open));$("#menu-toggle").textContent=open?"×":"☰"});
$("#main-nav").querySelectorAll("a").forEach(a=>a.addEventListener("click",()=>{$("#main-nav").classList.remove("open");$("#menu-toggle").setAttribute("aria-expanded","false");$("#menu-toggle").textContent="☰"}));
$("#dialog-close").addEventListener("click",()=>$("#department-dialog").close());
$("#department-dialog").addEventListener("click",e=>{if(e.target.id==="department-dialog")$("#department-dialog").close()});
$("#year").textContent=new Date().getFullYear();
applyLanguage("es");